def prompt(case, model):
    data = "\n".join(" | ".join(map(str, row)) for row in case["rows"])
    data_block = f"DATA (preserve every label and value exactly):\n{data}"
    if model == "qwen21":
        return (f"Create a finished bilingual-safe infographic in a landscape 3:2 canvas. Use the exact title \"{case['title']}\" and subtitle \"{case['subtitle']}\". "
                f"Chart: {case['chart']} Art direction: {case['style']}\n{data_block}\n"
                f"Key takeaway: \"{case['story']}\". {case['key']} Use a clear grid, readable typography, a strong title hierarchy, and data labels placed beside their matching marks. "
                "Render only the supplied text, with exact spelling, punctuation, units, category order, and numeric values. Do not add labels, numbers, legends, or claims. Make it a coherent article illustration, not a text-only table.")
    if model == "krea2":
        quoted = "\n".join("\"" + " · ".join(map(str, row)) + "\"" for row in case["rows"])
        return (f"Create a polished editorial infographic on a landscape 3:2 canvas. The headline reads \"{case['title']}\" and the subtitle reads \"{case['subtitle']}\". "
                f"Use {case['style']} The central visualization is {case['chart']} Put every value next to its correct category and preserve the given ordering. "
                f"The short takeaway reads \"{case['story']}\". The complete source labels and data are exactly:\n{quoted}\n"
                f"{case['key']} Give the data visualization most of the page, with excellent visual hierarchy, generous spacing, clear marks, and legible typography. "
                "Render the quoted wording and numbers faithfully; do not invent any extra text, labels, values, or decorative pseudo-writing. Keep the visual style attractive but the chart quantitatively honest.")
    rows = "\n".join("'" + " | ".join(map(str, row)) + "'" for row in case["rows"])
    return (f"Design one finished landscape 3:2 infographic. Headline: '{case['title']}'. Subtitle: '{case['subtitle']}'. "
            f"Visual style: {case['style']} Composition and chart: {case['chart']}\nExact data labels and values:\n{rows}\n"
            f"Takeaway: '{case['story']}'. {case['key']} Keep chart marks proportional, preserve label-value pairing and units, use a clean editorial hierarchy, and make the visualization the focal point. "
            "Render the quoted text accurately. Add no unsupported values, labels, series, or claims.")

for c in CASES:
    c["data_source"] = c.pop("source")

(ROOT / "casebook.json").write_text(json.dumps({"owner":"Sean","version":"v2","task_id":"remote-97ccaaac-e730-4c57-875c-c86954ca0518","cases":CASES}, ensure_ascii=False, indent=2)+"\n")
for model in ("qwen21", "krea2", "flux2"):
    d=ROOT/"prompts"/model; d.mkdir(parents=True,exist_ok=True)
    for c in CASES:
        (d/f"{c['id']}.txt").write_text(prompt(c,model)+"\n",encoding="utf-8")
print(f"Built {len(CASES)} cases and {len(CASES)*3} model-specific prompts in {ROOT}")
